const DECISION = "M80-BETA-ACCESS-QA-20260925"
const sha = (v: string | Uint8Array) => new Bun.CryptoHasher("sha256").update(v).digest("hex")
const uuid = (kind: string, n: number) => `${kind}000000-0000-4000-8000-${String(n).padStart(12, "0")}`
const identities = Array.from({ length: 8 }, (_, i) => ({ id: uuid("9a", i + 1), email: `qa-${i + 1}@beta.invalid` }))
const fixtureSource = { companies: [uuid("9b", 1), uuid("9b", 2)], identities }
const canonical = (value: any): string => Array.isArray(value) ? `[${value.map(canonical).join(",")}]` : value !== null && typeof value === "object" ? `{${Object.keys(value).sort().map(k => `${JSON.stringify(k)}:${canonical(value[k])}`).join(",")}}` : JSON.stringify(value)
const fixtureHash = sha(canonical({ profile: "neuvetra.beta-access.synthetic-fixture-manifest.v1", identities: identities.map(x => x.email), tenants: fixtureSource.companies.map((companyId, i) => ({ companyId, admissionId: uuid("9c", i + 1), displayLabel: `Synthetic QA ${i + 1}` })) }))
const fixture = {
